INSERT INTO `loai_san` (`id`, `ten`, `phan_loai`, `mo_ta`, `hoat_dong`, `ngay_tao`, `ngay_cap_nhat`) VALUES
(1, 'Bóng đá mini 5 người', 'SPORT', 'Mặt cỏ nhân tạo tiêu chuẩn, có hệ thống đèn chiếu sáng ban đêm.', 1, '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
(2, 'Cầu lông', 'SPORT', 'Thảm PVC chống trơn trượt, độ nảy chuẩn thi đấu.', 1, '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
(3, 'Tennis', 'SPORT', 'Sân cứng tiêu chuẩn, mặt sân phủ sơn Acrylic cao cấp.', 1, '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
(4, 'Pickleball', 'SPORT', 'Mặt sân đệm giảm chấn thương, hệ thống lưới và đèn đạt chuẩn.', 1, '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
(5, 'Khu sự kiện & tiệc', 'EVENT', 'Phòng tiệc, khu BBQ dùng cho sinh nhật, họp mặt, team building.', 1, '2026-10-08 00:58:33', '2026-10-08 00:58:33');
