(3, 2, 'Sân CL1', 'Sân số 1 trong nhà thi đấu có máy lạnh.', 'https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&w=600&q=80', NULL, 'ACTIVE', '2026-10-08 00:58:33', '2026-10-15 06:45:56'),
