(6, 3, 'Sân Tennis 1', 'Sân tennis có khán đài mini, đèn LED.', 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?auto=format&fit=crop&w=600&q=80', NULL, 'ACTIVE', '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
(7, 4, 'Sân Pickleball 1', 'Sân pickleball ngoài trời có mái che nắng.', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=600&q=80', NULL, 'ACTIVE', '2026-10-08 00:58:33', '2026-10-08 00:58:33'),
