(12, 'Gói Đại Tiệc BBQ Sân Vườn Hoàng Hôn', 'PACKAGE', 'gói', 2500000, 'Thịt bò Mỹ ướp sẵn, tôm càng nướng, xúc xích Đức, rau củ quả, bếp nướng than hoa, phục vụ bàn ghế sân vườn cho 15-25 khách', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=600&q=80', 'ACTIVE', '2026-10-14 16:00:47', '2026-10-14 16:00:47'),
(13, 'Gói Tiệc Sinh Nhật / Thôi Nôi Thể Thao', 'PACKAGE', 'gói', 3200000, 'Backdrop bóng bay thiết kế theo yêu cầu, bánh kem 3 tầng Tous Les Jours, nước ngọt, phòng tiệc máy lạnh riêng tư 20-35 khách', 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=600&q=80', 'ACTIVE', '2026-10-14 16:00:47', '2026-10-14 16:00:47'),
(14, 'Gói Gala Dinner & Team Building Doanh Nghiệp', 'PACKAGE', 'gói', 5500000, 'Dàn âm thanh karaoke công suất lớn, MC dẫn chương trình thể thao, tiệc mặn 6 món thịnh soạn, sân khấu riêng 30-60 khách', 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=600&q=80', 'ACTIVE', '2026-10-14 16:00:47', '2026-10-14 16:00:47'),
(15, 'Gói Tiệc Trà & Giao Lưu Thi Đấu', 'PACKAGE', 'gói', 800000, 'Trà hoa quả nhiệt đới, đĩa trái cây tươi nhập khẩu, bánh ngọt teabreak, không gian giao lưu ấm cúng cho 10-15 khách', 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=600&q=80', 'ACTIVE', '2026-10-14 16:00:47', '2026-10-14 16:00:47');
