INSERT INTO `su_kien` (`id`, `tieu_de`, `mo_ta_ngan`, `noi_dung`, `hinh_anh`, `ngay_bat_dau`, `ngay_ket_thuc`, `dia_diem`, `san_id`, `phi_tham_gia`, `phan_thuong`, `trang_thai`, `hotline_lh`, `ngay_tao`) VALUES
(1, 'Giải Vô Địch Cầu Lông Đôi Nam Nữ Sân 24/7 Mở Rộng 2026', 'Giải đấu phong trào quy mô lớn nhất năm quy tụ 32 cặp VĐV xuất sắc toàn thành phố.', 'Thể thức thi đấu vòng bảng loại trực tiếp theo chuẩn Liên đoàn Cầu lông. Mỗi bảng 4 cặp lấy 2 cặp nhất nhì vào tứ kết. Cơ sở tài trợ 100% nước uống, trái cây và hỗ trợ trọng tài chính thức. Cơ hội cọ xát, nâng cao kỹ chiến thuật và kết nối cộng đồng yêu cầu lông.', 'https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&w=800&q=80', '2026-10-25 08:00:00', '2026-10-25 18:30:00', 'Nhà thi đấu Cầu lông (Sân CL1, CL2, CL3)', 3, 200000, 'Cúp vô địch + Huy chương vàng + 10.000.000 ₫ tiền mặt', 'UPCOMING', '0900000001', '2026-10-14 16:05:22'),
(2, 'Cúp Tứ Hùng Bóng Đá Mini 5 Người - Mùa Thu 2026', 'Giải đấu tranh cúp giao hữu giữa 8 câu lạc bộ thể thao phong trào cuối tuần sôi động.', 'Đá knock-out trực tiếp hai hiệp 25 phút. Đội vô địch nhận cúp vàng danh giá và bộ trang phục thi đấu cao cấp. Có bình luận viên trực tiếp, quay phát livestream và chụp ảnh kỷ niệm chuyên nghiệp cho toàn bộ các trận đấu.', 'https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=800&q=80', '2026-10-18 17:30:00', '2026-10-18 21:30:00', 'Cụm Sân Bóng Đá Mini 5A & 5B', 1, 500000, 'Cúp vàng + Cờ lưu niệm + 15.000.000 ₫ giải nhất', 'HAPPENING', '0900000001', '2026-10-14 16:05:22'),
(3, 'Workshop & Ngày Hội Giao Lưu Pickleball Miễn Phí', 'Trải nghiệm môn thể thao hot nhất năm cùng Huấn luyện viên chuyên nghiệp có bằng quốc tế.', 'Chương trình hoàn toàn MIỄN PHÍ dành cho người mới bắt đầu và người chơi muốn hoàn thiện cú dink, smash. Được mượn vợt Pickleball và bóng thi đấu miễn phí. Có mini game bốc thăm trúng thưởng vợt cao cấp cuối buổi.', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=80', '2026-10-22 15:00:00', '2026-10-22 18:00:00', 'Khu Sân Pickleball 1 & 2', 7, 0, 'Tặng 3 vợt Pickleball carbon cho người may mắn', 'UPCOMING', '0900000002', '2026-10-14 16:05:22'),
(4, 'Đêm Hội Thể Thao & Đại Tiệc Âm Nhạc BBQ Cuối Tuần', 'Giao lưu thể thao kết hợp nướng BBQ sân vườn, ca nhạc Acoustic và rút thăm may mắn.', 'Khách tham gia được chơi thể thao tự do (bóng đá, cầu lông, pickleball) từ 16h-18h, sau đó cùng thưởng thức tiệc BBQ hải sản nướng ngoài trời, bia tươi và thưởng thức đêm nhạc Acoustic lãng mạn dưới ánh đèn trang trí lung linh.', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=800&q=80', '2026-10-31 16:30:00', '2026-10-31 22:30:00', 'Khu BBQ ngoài trời & Phòng tiệc A', 9, 350000, 'Voucher 1.000.000 ₫ đặt sân & quà tặng lưu niệm', 'UPCOMING', '0900000001', '2026-10-14 16:05:22');
